def resolve(path, cwd, links):
    max_links = 8
    links_followed = 0

    if not path.startswith('/'):
        path = cwd.rstrip('/') + '/' + path

    components = path.split('/')
    current = []

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            if current:
                current.pop()
        else:
            current.append(comp)
            candidate = '/' + '/'.join(current)

            if candidate in links:
                links_followed += 1
                if links_followed > max_links:
                    return None

                target = links[candidate]

                if target.startswith('/'):
                    current = []
                else:
                    if current:
                        current.pop()

                target_components = target.split('/')
                remaining = components[i:]

                components = target_components + remaining
                i = 0

    result = '/' + '/'.join(current)
    if result != '/':
        result = result.rstrip('/')

    return result

